/* Browser-only scientific intake. Files are never transmitted by this worker. */
const VERSION='stratax-browser/1.0',MAX_FILE=10*1024**3;
let cancelled=false,acks=new Map();
self.onmessage=event=>{const m=event.data;if(m.type==='ack'){acks.get(m.name)?.();acks.delete(m.name);}else if(m.type==='cancel')cancelled=true;else if(m.type==='read'){cancelled=false;read(m).catch(error=>postMessage({type:'error',message:error.message,code:error.code||'reader_failed'}));}};
const failure=(code,message)=>Object.assign(new Error(message),{code});
const value=(v,n)=>{if(v===null||v===undefined||v==='')return null;const num=Number(String(v).replace(/[dD]/,'E'));return Number.isFinite(num)?num===n?null:num:String(v);};
const col=(name,unit='',i=0)=>({id:'column-'+i,mnemonic:String(name),unit:String(unit||'')});
async function* lines(file,encoding='utf-8'){
 const reader=file.stream().pipeThrough(new TextDecoderStream(encoding)).getReader();let tail='';
 try{while(true){if(cancelled)throw failure('cancelled','Import cancelled.');const {value:part,done}=await reader.read();if(done)break;tail+=part;const rows=tail.split(/\r\n|\n|\r/);tail=rows.pop();for(const row of rows)yield row;if(tail.length>8*1024*1024)throw failure('line_limit','This record exceeds the browser reader limit. Export smaller rows or use a Cloud project.');}if(tail)yield tail;}finally{await reader.cancel();}
}
function cells(line,delimiter){if(delimiter==='whitespace')return line.trim().split(/\s+/);const out=[];let s='',quote=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'){if(quote&&line[i+1]==='"'){s+='"';i++;}else quote=!quote;}else if(c===delimiter&&!quote){out.push(s);s='';}else s+=c;}if(quote)throw failure('multiline_csv','Quoted multiline cells require the native Cloud reader or an export with single-line records.');out.push(s);return out;}
async function detect(file,family){const head=new Uint8Array(await file.slice(0,16384).arrayBuffer()),text=new TextDecoder().decode(head),ext=file.name.split('.').pop().toLowerCase();if(text.startsWith('LASF'))throw failure('lidar_las','This is LiDAR LAS, not well-log LAS. Select a supported spatial export.');if(/^\s*~(?:V|VERSION)/im.test(text)&&/^\s*VERS\s*\./im.test(text))return 'las';if(['csv','tsv','txt','asc','ascii','prn','dev','xyz','dat'].includes(ext)&&!head.includes(0))return 'table';if(['xlsx','xls'].includes(ext))return 'excel';if(['sgy','segy','su'].includes(ext))return 'seismic';if(['geojson','json'].includes(ext))return 'json';if(['kml'].includes(ext))return 'kml';if(['png','jpg','jpeg','bmp','gif','tif','tiff'].includes(ext))return 'image';if(family==='documents'&&!head.includes(0)&&!['pdf','docx'].includes(ext))return 'text';throw failure('conversion_required','This format needs the native Cloud reader. Local files stay on this device: retain the original or export LAS/CSV/XYZ/GeoJSON first.');}
async function read({file,family,options={},previewOnly=false}){
 if(file.size>MAX_FILE||!file.size)throw failure('file_size','Select a non-empty file up to 10 GiB.');
 let sha256='';
 if(options.fingerprintOnly||!previewOnly){importScripts('./vendor/sha256.umd.min.js');const hasher=await hashwasm.createSHA256();hasher.init();const reader=file.stream().getReader();let loaded=0;try{while(true){if(cancelled)throw failure('cancelled','Import cancelled.');const part=await reader.read();if(part.done)break;hasher.update(part.value);loaded+=part.value.length;if(loaded%(16*1024*1024)<part.value.length)postMessage({type:'progress',rows:0,hashing:true,loaded,total:file.size});}}finally{await reader.cancel();}sha256=hasher.digest('hex');if(options.fingerprintOnly){postMessage({type:'result',datasets:[],sha256,previewOnly:true});return;}}
 const format=await detect(file,family),datasets=[];
 let current,buffer=[],bufferBytes=0;
 async function start(columns,metadata={},name=file.name){current={id:crypto.randomUUID(),name,columns,rowCount:0,preview:[],chunks:[],metadata,issues:[],parserVersion:VERSION,family,well:options.well||metadata.well||'',references:options.references||{},mapping:options.mapping||{},schemaVersion:1};datasets.push(current);buffer=[];bufferBytes=0;}
 async function flush(){if(!buffer.length)return;const name=current.id+'-'+current.chunks.length+'.ndjson';const blob=new Blob(buffer,{type:'application/x-ndjson'});current.chunks.push({name,rows:buffer.length,size:blob.size});if(!previewOnly){const ack=new Promise(resolve=>acks.set(name,resolve));postMessage({type:'chunk',name,blob});await ack;}buffer=[];bufferBytes=0;}
 async function row(values){if(values.length!==current.columns.length)throw failure('column_count','A row does not match the column definition. Check delimiter, header and mapping.');for(const [role,rawIndex]of Object.entries(options.mapping||{})){if(rawIndex==='')continue;const index=Number(rawIndex),v=values[index];if(!Number.isInteger(index)||index<0||index>=values.length){if(!current.issues.some(i=>i.code==='invalid_mapping'))current.issues.push({code:'invalid_mapping',severity:'blocking',message:'A mapped column is absent from this dataset.'});continue;}const rad=options.references?.angleUnit==='radians',bounds={inclination:[0,rad?Math.PI:180],azimuth:[0,rad?2*Math.PI:360],latitude:[-90,90],longitude:[-180,180]}[role];if(bounds&&typeof v==='number'&&(v<bounds[0]||v>bounds[1])&&!current.issues.some(i=>i.code==='range_'+role))current.issues.push({code:'range_'+role,severity:'blocking',message:role+' values exceed the expected range.'});}current.rowCount++;const encoded=JSON.stringify(values)+'\n';if(current.preview.length<60&&JSON.stringify(current.preview).length+encoded.length<250000)current.preview.push(values);if(!previewOnly){buffer.push(encoded);bufferBytes+=encoded.length;if(buffer.length>=5000||bufferBytes>=4*1024*1024)await flush();}if(current.rowCount%5000===0)postMessage({type:'progress',rows:current.rowCount});}
 if(format==='las'){
  let section='',columns=[],headers={},version='',nullValue=-999.25,pending=[],wrapped=false;
  for await(const line of lines(file,options.encoding||'utf-8')){
   if(!line.trim()||line.trim().startsWith('#'))continue;
   if(line.trim().startsWith('~')){if(current){await flush();current=null;}section=line.trim().slice(1).split(':')[0].trim().toUpperCase();if(section.startsWith('C')||section.endsWith('_DEFINITION'))columns=[];if(section.startsWith('A')||section.endsWith('_DATA')){if(!['1.2','2.0','3.0'].includes(version))throw failure('las_version','Export LAS 1.2, 2.0 or 3.0 for this reader.');if(!columns.length)throw failure('las_curves','No matching curve definition was found.');await start(columns,{format:'LAS',version,headers:structuredClone(headers),null:nullValue,well:headers.WELL?.value||'',coordinatesConfirmed:false});}continue;}
   if(current){const tokens=line.trim().split(/[\s,]+/);if(wrapped){pending.push(...tokens);while(pending.length>=columns.length){await row(pending.splice(0,columns.length).map(v=>value(v,nullValue)));}}else await row(tokens.map(v=>value(v,nullValue)));if(previewOnly&&current.rowCount>=60)break;}
   else{const m=line.match(/^\s*([^\s.]+)\s*\.([^\s:]*)\s*([^:]*)(?::(.*))?$/);if(!m)continue;const entry={mnemonic:m[1],unit:m[2],value:m[3].trim(),description:(m[4]||'').trim()};if(section.startsWith('C')||section.endsWith('_DEFINITION'))columns.push({...col(m[1],m[2],columns.length),description:entry.description});else{headers[m[1].toUpperCase()]=entry;if(m[1].toUpperCase()==='VERS')version=Number(entry.value).toFixed(1);if(m[1].toUpperCase()==='NULL')nullValue=Number(entry.value);if(m[1].toUpperCase()==='WRAP')wrapped=entry.value.toUpperCase()==='YES';}}
  }
  if(pending.length&&!previewOnly)throw failure('las_tail','The final wrapped LAS record is incomplete.');
 }else if(format==='table'){
  let index=0,delimiter=options.delimiter||'',columns;const headerRow=Number(options.headerRow||1);
  for await(const line of lines(file,options.encoding||'utf-8')){index++;if(index<headerRow||!line.trim()||line.trim().startsWith('#'))continue;if(!delimiter)delimiter=line.includes('\t')?'\t':line.includes(',')?',':line.includes(';')?';':'whitespace';let values;if(options.widths?.length){let pos=0;values=options.widths.map(w=>{const out=line.slice(pos,pos+Number(w)).trim();pos+=Number(w);return out;});}else values=cells(line,delimiter);if(!columns){columns=values.map((v,i)=>col(options.noHeader?'Column '+(i+1):v,options.units?.[i]||'',i));await start(columns,{format:'ASCII',delimiter});if(!options.noHeader)continue;}await row(values.map(v=>value(v,options.null===''||options.null===undefined?undefined:Number(options.null))));if(previewOnly&&current.rowCount>=60)break;}
 }else if(format==='excel'){
  if(file.size>64*1024*1024)throw failure('excel_budget','Export selected sheets to CSV for browser imports larger than 64 MiB.');
  importScripts('./vendor/xlsx.full.min.js');const book=XLSX.read(await file.arrayBuffer(),{type:'array',cellDates:false});const sheet=options.sheet||book.SheetNames[0];if(!book.Sheets[sheet])throw failure('sheet_missing','The selected worksheet does not exist.');const rows=XLSX.utils.sheet_to_json(book.Sheets[sheet],{header:1,defval:null,raw:true,range:Number(options.headerRow||1)-1});const names=rows.shift();if(!names)throw failure('empty_sheet','The selected worksheet is empty.');await start(names.map((n,i)=>col(n,options.units?.[i]||'',i)),{format:'Excel',sheet,sheets:book.SheetNames});for(const values of (previewOnly?rows.slice(0,60):rows))await row(names.map((_,i)=>value(values[i],options.null===''||options.null===undefined?undefined:Number(options.null))));
 }else if(format==='seismic'){
  const su=file.name.toLowerCase().endsWith('.su'),little=options.endian==='little',head=new DataView(await file.slice(0,3600).arrayBuffer());if(head.byteLength<(su?240:3600))throw failure('seismic_header','This file is too short to contain a seismic header.');const count=su?head.getUint16(114,little):head.getUint16(3220,little),code=su?5:head.getUint16(3224,little),sizes={1:4,2:4,3:2,5:4,6:8,7:3,8:1,9:8,10:4,11:2,12:8,15:3,16:1},size=sizes[code];if(!size||!count)throw failure('seismic_format','Confirm byte order and sample format, or use a Cloud native reader.');let offset=su?0:3600;if(!su){const extra=head.getInt16(3504,little);if(extra<0)throw failure('extended_headers','Variable extended headers need the native Cloud reader.');offset+=extra*3200;}const stride=240+count*size,traceCount=Math.floor((file.size-offset)/stride);if(offset+traceCount*stride!==file.size)throw failure('variable_traces','This SEG-Y has extended/variable trace layouts. Use the native Cloud reader or a standard SEG-Y export.');const keys={inline:189,crossline:193,x:181,y:185,scalar:71,...options.headerBytes};await start(['Trace','Inline','Crossline','X','Y','Coordinate scalar'].map((n,i)=>col(n,'',i)),{format:su?'SU':'SEG-Y',sampleCount:count,sampleFormat:code,traceCount,headerBytes:keys,endian:little?'little':'big',originalGeometryPreserved:true});for(let i=0;i<traceCount;i++){if(cancelled)throw failure('cancelled','Import cancelled.');const h=new DataView(await file.slice(offset+i*stride,offset+i*stride+240).arrayBuffer());const scale=h.getInt16(Number(keys.scalar)-1,little),factor=scale>0?scale:scale<0?1/Math.abs(scale):1;await row([i,h.getInt32(Number(keys.inline)-1,little),h.getInt32(Number(keys.crossline)-1,little),h.getInt32(Number(keys.x)-1,little)*factor,h.getInt32(Number(keys.y)-1,little)*factor,scale]);if(previewOnly&&i>=59)break;}
 }else if(format==='json'){
  if(file.size>32*1024*1024)throw failure('json_budget','Use smaller GeoJSON/JSON exports or a Cloud project for this file.');const data=JSON.parse(await file.text());if(data.type==='FeatureCollection'){await start(['Feature ID','Geometry','Properties'].map((n,i)=>col(n,'',i)),{format:'GeoJSON',crs:data.crs||null});for(const [i,f]of data.features.entries())await row([f.id??i,f.geometry,f.properties]);}else if(options.jsonPath){const selected=options.jsonPath.split('.').reduce((v,k)=>v?.[k],data);if(!Array.isArray(selected)||!selected.length)throw failure('json_mapping','Select an array of records in this JSON file.');const names=Object.keys(selected[0]);await start(names.map((n,i)=>col(n,'',i)),{format:'mapped JSON',path:options.jsonPath});for(const item of selected)await row(names.map(n=>item[n]??null));}else throw failure('schema_required','Generic JSON needs an explicit record-array path.');
 }else if(format==='image'){
  const bitmap=await createImageBitmap(file);await start([col('Attribute','',0),col('Value','',1)],{format:'Image',ocrPerformed:false});await row(['Width',bitmap.width]);await row(['Height',bitmap.height]);bitmap.close();
 }else if(format==='text'){
  await start([col('Line','',0),col('Text','',1)],{format:'Text'});let i=0;for await(const line of lines(file)){await row([++i,line]);if(previewOnly&&i>=60)break;}
 }else throw failure('conversion_required','Retain this original or export a supported browser-readable file.');
 await flush();if(!datasets.length)throw failure('no_datasets','No readable dataset was found.');
 for(const d of datasets){const required={deviation:options.surveyMethod==='coordinates'?['md','x','y','z']:['md','inclination','azimuth'],tops:['name','depth'],checkshots:['depth','time'],well_headers:['well'],production:['date']}[family]||[];for(const role of required)if(String(options.mapping?.[role]??'')==='')d.issues.push({code:'mapping_'+role,severity:'blocking',message:'Map '+role+' before activation.'});if(family==='checkshots'&&(!options.references?.timeConvention||!options.references?.timeUnit))d.issues.push({code:'time_reference',severity:'warning',message:'Confirm time convention and units before scientific use.'});if(['seismic','surfaces','models'].includes(family)&&!options.references?.domain)d.issues.push({code:'domain',severity:'warning',message:'Confirm time or depth domain before scientific use.'});if(d.columns.some(c=>!c.unit||c.unit==='UNKNOWN')&&['logs','arrays'].includes(family))d.issues.push({code:'unknown_units',severity:'warning',message:'Some curve units are unconfirmed.'});if(['logs','deviation','tops','checkshots','core','pressure'].includes(family)&&!options.references?.depthReference)d.issues.push({code:'depth_reference',severity:'warning',message:'Depth reference is unconfirmed.'});if(d.metadata.headers?.LAT||['well_headers','seismic','spatial','surfaces','models'].includes(family))if(!options.references?.crs)d.issues.push({code:'unconfirmed_crs',severity:'warning',message:'Source CRS/datum is unconfirmed. Coordinates are not activated on the map.'});if(family==='deviation'&&!options.references?.northReference)d.issues.push({code:'north_reference',severity:'warning',message:'North reference is unconfirmed; no trajectory is calculated.'});d.status=d.issues.length?'retained/unresolved':'ready';}
 for(const dataset of datasets){dataset.sourceSha256=sha256;for(const [i,c]of dataset.columns.entries()){const unit=options.units?.[i];if(unit)c.effectiveUnit=unit;}if(dataset.columns.every(c=>c.effectiveUnit||c.unit&&c.unit!=='UNKNOWN'))dataset.issues=dataset.issues.filter(i=>i.code!=='unknown_units');dataset.status=dataset.issues.length?'retained/unresolved':'ready';}
 postMessage({type:'result',datasets,format,previewOnly,sha256});
}
